        for ($i = count($data) - 1; $i >= 0; $i--) {
            $builder->putOffset($data[$i]);
        }
        return $builder->endVector();
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param int $numElems
     * @return void
     */
    public static function startSAA_CONTOURSVector(FlatBufferBuilder $builder, $numElems)
    {
        $builder->startVector(4, $numElems, 4);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param VectorOffset
     * @return void
     */
    public static function addSPACE_WEATHER_REFS(FlatBufferBuilder $builder, $SPACE_WEATHER_REFS)
    {
        $builder->addOffsetX(26, $SPACE_WEATHER_REFS, 0);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param array offset array
     * @return int vector offset
     */
    public static function createSPACE_WEATHER_REFSVector(FlatBufferBuilder $builder, array $data)
    {
        $builder->startVector(4, count($data), 4);
        for ($i = count($data) - 1; $i >= 0; $i--) {
            $builder->putOffset($data[$i]);
        }
        return $builder->endVector();
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param int $numElems
     * @return void
     */
    public static function startSPACE_WEATHER_REFSVector(FlatBufferBuilder $builder, $numElems)
    {
        $builder->startVector(4, $numElems, 4);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param VectorOffset
     * @return void
     */
    public static function addPROVENANCE(FlatBufferBuilder $builder, $PROVENANCE)
    {
        $builder->addOffsetX(27, $PROVENANCE, 0);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endRBF(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // RBF_ID
        $builder->required($o, 6);  // BODY_NAME
        $builder->required($o, 22);  // UNITS
        $builder->required($o, 24);  // EPOCH
        $builder->required($o, 58);  // PROVENANCE
        return $o;
    }

    public static function finishRBFBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, '$RBF');
    }
}
